import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Metamodell bearbeiten","description":"","frontmatter":{"title":"Metamodell bearbeiten","covers":{"screens":[],"stories":["US-032","US-137","US-140"]}},"headers":[],"relativePath":"de/administration/metamodel-editing.md","filePath":"de/administration/metamodel-editing.md"}`),a={name:`de/administration/metamodel-editing.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="metamodell-bearbeiten" tabindex="-1">Metamodell bearbeiten <a class="header-anchor" href="#metamodell-bearbeiten" aria-label="Permalink to “Metamodell bearbeiten”">​</a></h1><p>Neben dem Import von Paketen (siehe <a href="./metamodel-packages">Metamodell-Pakete</a>) pflegst du Entitätstypen und Eigenschaften deiner eigenen Organisation. Das Formular im Webportal folgt; bis dahin bearbeitest du das Metamodell über die API. Alle Operationen verlangen <code>metamodel:write</code> (Rolle <code>metamodel-admin</code>) und werden mit deinem Namen im Audit-Trail festgehalten.</p><h2 id="entitatstypen" tabindex="-1">Entitätstypen <a class="header-anchor" href="#entitatstypen" aria-label="Permalink to “Entitätstypen”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;SecurityZone&quot;, &quot;abbreviation&quot;: &quot;SZ&quot;, &quot;configId&quot;: &quot;00000000-0000-0000-0000-000000000001&quot;}&#39;</span></span></code></pre></div><ul><li>Entitätstypen, die du anlegst, erhalten den Scope <code>organization</code> und sind sofort für Entitäten nutzbar.</li><li>Namen sind über alle Entitätstypen eindeutig, unabhängig von Groß- und Kleinschreibung: <code>application component</code> wird mit <code>409</code> (<code>name-taken</code>) abgelehnt, solange <em>Application Component</em> existiert.</li><li>Du änderst und löschst nur eigene Entitätstypen. Eingebaute und importierte sind schreibgeschützt (<code>409</code>, <code>read-only-metatype</code>); eigene Eigenschaften kannst du ihnen trotzdem hinzufügen.</li><li>Ein Entitätstyp mit Entitäten – auch gelöschten –, einer, den ein Katalog verwendet, oder einer, der Basistyp eines anderen Typs ist, lässt sich nicht löschen (<code>409</code>, <code>in-use</code>, mit der Anzahl der Entitäten in <code>count</code>).</li><li>Verbindungstypen folgen in einer späteren Version; <code>isConnection: true</code> wird abgelehnt.</li></ul><h3 id="basistypen" tabindex="-1">Basistypen <a class="header-anchor" href="#basistypen" aria-label="Permalink to “Basistypen”">​</a></h3><p>Mit <code>baseMetatypeId</code> erbt ein Entitätstyp alle Eigenschaften seines Basistyps und von dessen Basistypen. <code>GET /metamodel/metatypes/{id}</code> listet die geerbten Eigenschaften mit <code>inheritedFrom</code>. Eine Eigenschaft darf in einer Kette nur einmal vorkommen; Basistypen dürfen keinen Zyklus bilden. Pakete können einen Basistyp aus demselben Paket oder einen eingebauten Typ nennen.</p><p>Änderst du den Basistyp eines eigenen Entitätstyps, verliert er die Eigenschaften des alten Basistyps – mit ihren Werten, siehe unten – und erhält die des neuen.</p><h2 id="eigenschaften" tabindex="-1">Eigenschaften <a class="header-anchor" href="#eigenschaften" aria-label="Permalink to “Eigenschaften”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/property-definitions&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;Trust Level&quot;, &quot;dataType&quot;: &quot;enum&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/property-definitions/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/enum-values&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: &quot;high&quot;}&#39;</span></span></code></pre></div><ul><li>Datentypen: <code>string</code>, <code>text</code>, <code>integer</code>, <code>boolean</code>, <code>date</code>, <code>url</code> und <code>enum</code>. Referenz-Eigenschaften folgen mit den Verbindungstypen.</li><li>OEA leitet den Speichernamen <code>sqlColumnName</code> aus dem Namen ab, zum Beispiel <code>trust_level</code>. Er wird in Auswertungen verwendet und ändert sich nie, auch nicht, wenn du die Eigenschaft umbenennst.</li><li>Den Datentyp kannst du nicht mehr ändern, sobald Entitäten Werte für die Eigenschaft haben, auch in ihrer Historie.</li><li>Eine Eigenschaft, die noch einem Entitätstyp zugeordnet ist, lässt sich nicht löschen. Eine Eigenschaft, die in der Historie von Entitäten vorkommt, wird stattdessen stillgelegt: Sie verschwindet aus den Listen, und ihr Name bleibt belegt.</li><li>Eigenschaftskategorien (<code>/metamodel/property-categories</code>) gruppieren Eigenschaften; eine Kategorie mit Eigenschaften lässt sich nicht löschen.</li></ul><h2 id="eigenschaften-entitatstypen-zuordnen" tabindex="-1">Eigenschaften Entitätstypen zuordnen <a class="header-anchor" href="#eigenschaften-entitatstypen-zuordnen" aria-label="Permalink to “Eigenschaften Entitätstypen zuordnen”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/property-mappings&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;propertyDefId&quot;: &quot;&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;&quot;, &quot;necessity&quot;: &quot;mandatory&quot;}&#39;</span></span></code></pre></div><ul><li>Du ordnest eigene Eigenschaften jedem Entitätstyp zu, auch importierten und eingebauten. Die Eigenschaften eines Pakets bleiben unverändert.</li><li>Die Notwendigkeit ist <code>mandatory</code>, <code>warning</code> oder <code>optional</code>; <code>validFrom</code> ist standardmäßig heute.</li></ul><h3 id="eine-neue-pflicht-eigenschaft" tabindex="-1">Eine neue Pflicht-Eigenschaft <a class="header-anchor" href="#eine-neue-pflicht-eigenschaft" aria-label="Permalink to “Eine neue Pflicht-Eigenschaft”">​</a></h3><p>Das Zuordnen einer Pflicht-Eigenschaft gelingt immer, auch wenn Entitäten existieren. OEA markiert jede bestehende Entität des Typs und seiner Subtypen ohne Wert; die Antwort nennt die Anzahl in <code>markedEntityCount</code>. Eine markierte Entität funktioniert weiter, bis jemand sie ändert: Das Speichern ohne den Wert wird mit <code>MANDATORY_MISSING</code> abgelehnt. Setzt du den Wert, verschwindet die Markierung.</p><p>Pflicht-Eigenschaften werden nur geprüft, wo die schreibende Person sie ändern kann. Eigenschaften mit eingeschränkter Sichtbarkeit lassen sich noch nicht schreiben und werden deshalb nie als fehlend gemeldet.</p><h3 id="die-notwendigkeit-per-stichtag-andern" tabindex="-1">Die Notwendigkeit per Stichtag ändern <a class="header-anchor" href="#die-notwendigkeit-per-stichtag-andern" aria-label="Permalink to “Die Notwendigkeit per Stichtag ändern”">​</a></h3><p>Ein Metamodell entwickelt sich weiter: Eine Eigenschaft, die heute optional ist, kann ab einem bestimmten Datum Pflicht werden. Ordne die Eigenschaft erneut zu, mit der neuen Notwendigkeit und dem Datum, ab dem sie gilt:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/property-mappings&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;propertyDefId&quot;: &quot;&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;&quot;, &quot;necessity&quot;: &quot;mandatory&quot;, &quot;validFrom&quot;: &quot;2027-01-01&quot;}&#39;</span></span></code></pre></div><ul><li>Die früheren Einträge bleiben; es gilt der Eintrag mit dem spätesten Datum, das nicht nach heute liegt. Ein zweiter Eintrag mit demselben Datum wird mit <code>409</code> (<code>conflict</code>) abgelehnt.</li><li>Ein Datum in der Vergangenheit gilt sofort. Bei einem Datum in der Zukunft markiert OEA die Entitäten ohne Wert, sobald das Datum erreicht ist – spätestens etwa zehn Minuten nach Mitternacht (UTC) –, und schreibt das Audit-Event <code>metamodel.mapping-effective</code>. Ist eine Eigenschaft nicht mehr Pflicht, verschwinden ihre Markierungen.</li><li>Das geht auch für die Eigenschaften eines Pakets, zum Beispiel um <em>Status</em> zur Pflicht zu machen. Dein Eintrag hat den Scope <code>organization</code>; das Paket bleibt unverändert. Bringt das Paket selbst einen Eintrag mit demselben Datum, gewinnt deiner.</li><li>Einträge machst du am Entitätstyp, dem die Eigenschaft zugeordnet ist, nicht an seinen Subtypen.</li><li><code>GET /metamodel/metatypes/{id}/property-mappings</code> zeigt die heute gültigen Einträge; mit <code>?includeHistory=true</code> erhältst du alle Einträge mit ihrem <code>state</code> (<code>past</code>, <code>active</code>, <code>future</code>).</li><li>Um einen Eintrag zu korrigieren, entfernst du ihn und legst einen neuen an. Das Entfernen eines von mehreren Einträgen einer Eigenschaft löscht keine Werte.</li></ul><h3 id="eine-eigenschaft-entfernen" tabindex="-1">Eine Eigenschaft entfernen <a class="header-anchor" href="#eine-eigenschaft-entfernen" aria-label="Permalink to “Eine Eigenschaft entfernen”">​</a></h3><p>Das Entfernen der Zuordnung einer eigenen Eigenschaft – oder eines deiner Einträge – ist immer möglich:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/property-mappings/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MAPPING</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Werte werden gelöscht</p><p>Hat der Entitätstyp die Eigenschaft danach nicht mehr und haben Entitäten des Typs oder seiner Subtypen Werte dafür, werden diese Werte gelöscht. Jede betroffene Entität erhält eine neue Version; der entfernte Wert bleibt in ihrer Historie sichtbar. Das Audit-Event <code>metamodel.mapping-deleted</code> nennt die Anzahl der betroffenen Entitäten. Das Löschen eines Werts einer Enum-Eigenschaft wirkt genauso auf die Entitäten mit diesem Wert.</p></div><h2 id="translating-labels" tabindex="-1">Labels übersetzen <a class="header-anchor" href="#translating-labels" aria-label="Permalink to “Labels übersetzen”">​</a></h2><p>Benutzer sehen die Namen von Entitätstypen, Kategorien und Eigenschaften sowie die Werte von Enum-Eigenschaften in der Sprache ihrer Oberfläche (siehe <a href="./../usage/login#your-profile">Dein Profil</a>). Die Übersetzungen pflegst du pro Sprache – <code>de</code>, <code>en</code>, <code>fr</code> oder <code>it</code> – über die API, bis das Formular im Webportal folgt:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/labels/de&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # jedes Element mit Name, Paket-Label und deinem Label</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/labels/de&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;labels&quot;: {&quot;metatype.&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;.name&quot;: &quot;Anwendungskomponente&quot;, &quot;enum-value.&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VALUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;.label&quot;: &quot;&quot;}}&#39;</span></span></code></pre></div><ul><li>Ein Label-Schlüssel nennt das Element mit seiner Kennung: <code>metatype.{id}.name</code>, <code>property-category.{id}.name</code>, <code>property-def.{id}.label</code> oder <code>enum-value.{id}.label</code>. Schlüssel, die du nicht nennst, bleiben unverändert; ein leerer Text entfernt dein Label. Texte haben höchstens 200 Zeichen.</li><li>Du kannst jedes Element übersetzen, auch die eines Pakets. Dein Label gewinnt gegenüber dem Label des Pakets; ohne beide sehen Benutzer den Namen in deiner Unternehmenssprache.</li><li>Ein unbekannter Schlüssel lehnt die ganze Änderung mit <code>422</code> (<code>validation-failed</code>) ab und nennt die Schlüssel. Jede Änderung schreibt das Audit-Event <code>metamodel.labels-changed</code>.</li><li>Offene Webportale übernehmen eine Änderung innerhalb von fünf Minuten, ohne Neuladen.</li></ul><h2 id="eigene-eigenschaften-beim-erneuten-paketimport" tabindex="-1">Eigene Eigenschaften beim erneuten Paketimport <a class="header-anchor" href="#eigene-eigenschaften-beim-erneuten-paketimport" aria-label="Permalink to “Eigene Eigenschaften beim erneuten Paketimport”">​</a></h2><p>Wird ein Paket erneut importiert, ersetzt es seine eigenen Eigenschaften an seinen Entitätstypen. Ob deine eigenen Eigenschaften und Einträge an diesen Typen bleiben, hängt von deiner Arbeitsweise ab, deshalb konfigurierst du es:</p><ul><li><strong>Global</strong> mit <code>PUT /metamodel/settings/reimport-policy</code> und <code>{&quot;organizationMappings&quot;: &quot;keep&quot;}</code> (Standard) oder <code>&quot;remove&quot;</code>.</li><li><strong>Pro Entitätstyp</strong> mit <code>PUT /metamodel/metatypes/{id}/reimport-policy</code> und <code>inherit</code> (Standard), <code>keep</code> oder <code>remove</code>. <code>inherit</code> übernimmt die Einstellung des Basistyps; ganz oben in der Kette gilt die globale Einstellung. <code>GET /metamodel/metatypes/{id}</code> zeigt den eigenen Wert in <code>reimportPolicy</code> und den geltenden in <code>effectiveReimportPolicy</code>.</li></ul><p>Das Entfernen beim erneuten Import löscht die Werte wie oben beschrieben.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};